function mscBtnH() { const el = document.getElementById('reg_open'); if (el && el.offsetHeight) M_.bh = el.offsetHeight; if (!M_.bh) { try { const b = document.createElement('button'); b.className = 'btn'; b.style.cssText = 'font-size:15px;padding:10px 18px;position:absolute;visibility:hidden;left:-9999px;top:0'; b.textContent = '📥 등록'; document.body.appendChild(b); M_.bh = b.offsetHeight; b.remove(); } catch (e) {} } return M_.bh || 42; }
/* (3차 · 정범님 10/27 16:45) 캐릭터 크기 단계 — 기기별(me.size) · 기본 = '크게'(정범님이 처음 정한 등록 단추 높이 4배 · 화면 높이 24%까지) · 더 큰 단계는 화면 높이 60%까지 · 클릭은 그대로 뒤로 지나감 */
const MSC_SIZES = [{ k: 'xs', n: '아주 작게', x: 1.5 }, { k: 's', n: '작게', x: 2 }, { k: 'm', n: '보통', x: 3 }, { k: 'l', n: '크게', x: 4 }, { k: 'xl', n: '아주 크게', x: 5.5 }, { k: 'xxl', n: '특대', x: 7 }, { k: 'c8', n: '대형 8cm', cm: 8 }, { k: 'c10', n: '대형 10cm', cm: 10 }, { k: 'c12', n: '초대형 12cm', cm: 12 }, { k: 'c14', n: '최대 14cm', cm: 14 }]; /* (정범님 10/27 20:39) 실제 길이 단계 8·10·12·14cm — px = cm ÷ 2.54 × mscPpi() · 화면 높이 92%까지 */
/* (r16i ④ · 정범님 10/30 00:30 '휴대폰에서 캐릭터가 화면 70% 넘게 덮음') 휴대폰은 따로 정한 크기 단계(화면 높이의 몇 %) · 기본 = 35% · 이 기기 칸의 psize에 저장(예전 size — PC 단계·12cm 같은 실제 길이 — 는 휴대폰에서 쓰지 않음) · 가장 커도 화면 높이 60% */
const MSC_PSIZES = [{ k: 'p20', n: '아주 작게', fr: 0.2 }, { k: 'p25', n: '작게', fr: 0.25 }, { k: 'p30', n: '조금 작게', fr: 0.3 }, { k: 'p35', n: '휴대폰 기본', fr: 0.35 }, { k: 'p42', n: '조금 크게', fr: 0.42 }, { k: 'p50', n: '크게', fr: 0.5 }, { k: 'p60', n: '아주 크게', fr: 0.6 }];
/* (r16i ④ · 감사 S-28 '휴대폰에서 캐릭터를 누르면 뒤 웹앱 단추가 같이 눌려 다른 화면으로 넘어감') 손가락 기기에서는 ① 캐릭터 몸(그려진 부분)이 누름을 받고(뒤로 지나가지 않음) ② 캐릭터에서 시작한 누름 뒤 0.8초 안에 생기는 click이 캐릭터 밖(움직이는 몸짓으로 캐릭터가 비켜난 자리 · 웹앱)에 떨어지면 버림 — 끌기(5px 넘게 움직임)와 탭은 mscDragBind가 나눔 */
function mscTouchDev() { try { return matchMedia('(pointer:coarse)').matches || mscPhone(); } catch (e) { return false; } }
function mscTapGuard() { if (M_.tapG) return; M_.tapG = 1; const inChr = (t) => !!(t && t.closest && t.closest(MSC_CHR_SEL));
  window.addEventListener('pointerdown', (e) => { if (inChr(e.target)) M_.chrDown = { t: performance.now(), x: e.clientX, y: e.clientY, touch: e.pointerType !== 'mouse' }; }, true);
  const eat = (e) => { const d = M_.chrDown; if (!d || inChr(e.target)) return; if (performance.now() - d.t > 800) { M_.chrDown = null; return; } if (e.clientX != null && Math.hypot(e.clientX - d.x, e.clientY - d.y) > 60) return; e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation(); if (e.type === 'click') { M_.chrDown = null; M_.tapEaten = (M_.tapEaten || 0) + 1; } };
  window.addEventListener('click', eat, true); window.addEventListener('dblclick', eat, true); window.addEventListener('contextmenu', eat, true); }
function mscPhone() { try { const sw = Math.min(screen.width || innerWidth, screen.height || innerHeight); return sw <= 520 && (matchMedia('(pointer:coarse)').matches || /Android|iPhone|iPod/i.test(navigator.userAgent)); } catch (e) { return false; } }
const mscSizes = () => (mscPhone() ? MSC_PSIZES : MSC_SIZES); const mscSizeKey = () => (mscPhone() ? 'psize' : 'size');
function mscVh() { const ih = window.innerHeight || 700; M_.vhMax = Math.max(M_.vhMax || 0, ih); return Math.min(Math.max(ih, M_.vhMax), Math.max(ih, screen.height || ih)); } /* 휴대폰 주소창이 숨거나 나타나 높이가 바뀌어도 캐릭터 크기가 출렁이지 않게 — 본 가장 큰 높이 */
