function mscSize(st, view) { st = st || mscSizeStep(); const bh = mscBtnH(); const bust = (view || mscViewOf(mscMine())) === 'bust', ar = bust ? 0.84 : 0.5; const hW = st.cm || st.fr ? Math.max(120, (window.innerWidth - 90) / ar) : Infinity; const t = st.fr ? (Math.min(mscVh() * 0.6, hW) * st.fr) / 0.6 : st.cm ? (st.cm / 2.54) * mscPpi() : bh * st.x; const cap = st.fr ? 0.6 : st.cm ? (mscPhone() ? 0.6 : 0.92) : st.x <= 4 ? 0.24 : 0.6; const hH = (st.fr ? mscVh() : window.innerHeight) * cap; /* (r16i ④ · 감사 S-21 'c14가 c12보다 안 커짐') 휴대폰 단계는 '이 화면에서 가장 크게(높이 60% · 너비 상한)'에 대한 비율이라 단계마다 반드시 커짐(반신은 너비에 먼저 걸림) */ const h = Math.round(Math.min(t, hH, hW)); return { h, w: Math.round(h * ar), bh, x: Math.round((h / bh) * 10) / 10, t: Math.round(t), cap, why: h + 1 < t ? (hW < hH ? 'w' : 'h') : '' }; } /* why = 줄인 까닭(h 화면 높이 · w 화면 너비) */
/* 화면 px → 실제 cm 어림: 기기 화면 크기·devicePixelRatio로 'CSS px가 1인치에 몇 개'를 짐작(휴대폰 ≈160 · 태블릿 ≈132 · 고해상도 노트북 ≈125 · 배율 쓰는 노트북 ≈112 · 보통 모니터 ≈96) — 기기마다 조금 다를 수 있음 */
function mscPpi() { const sw = Math.min(screen.width || innerWidth, screen.height || innerHeight); const dpr = window.devicePixelRatio || 1; return sw <= 520 ? 160 : sw <= 900 ? 132 : dpr >= 1.75 ? 125 : dpr >= 1.2 ? 112 : 96; }
function mscCm(px) { return Math.round((px / mscPpi()) * 25.4) / 10; }
function mscLike(cm) { return cm < 2.5 ? '엄지손톱쯤' : cm < 4 ? '엄지손가락 한 마디쯤' : cm < 6.2 ? '신용카드 짧은 변(5.4cm)쯤' : cm < 8.5 ? '스마트폰 너비(7cm)쯤' : cm < 11 ? '손바닥 너비(약 9~10cm)쯤' : cm < 13 ? '손바닥 길이쯤(손목~손끝 약 17cm보다 조금 작게)' : '스마트폰 세로 길이(약 14~15cm)쯤'; }
function mscSizeTxt(st) { const s = mscSize(st); const cm = mscCm(s.h); return `<b>${st.n}</b> · ${st.fr ? `화면 높이 ${Math.round(st.fr * 100)}% · ` : ''}높이 ${s.h}px ≈ 약 ${cm}cm(어림) · ${mscLike(cm)} · 등록 단추 ${s.x}배${s.why === 'h' ? ` <small>(화면 높이 ${Math.round(s.cap * 100)}%로 줄임)</small>` : s.why === 'w' ? ` <small>(화면 너비에 맞춰 줄임)</small>` : ''}`; }

