  if (kind === 'cheer') { const n = M_.q.filter((x) => x.kind === 'cheer').length; if (n > 1) M_.q.splice(M_.q.findIndex((x) => x.kind === 'cheer'), 1); } /* (13차) 응원은 줄에 하나만(새 문구로) — 버리지 않음 */
