function mscBadWait() { const P = mscPend(); const td = todayStr(); const out = []; Object.entries(P).forEach(([k, x]) => { if (x.k !== 'bad') return; if (x.day !== td || mscAcked(k)) return mscPendDel(k); out.push({ ...x, key: k }); }); return out; }
function mscRemRange(w) { const d = mscCfg().dur; const a = Math.max(0.05, +(w === 'b' ? d.badRemMin : d.remMin) || 1); return [a, Math.max(a, +(w === 'b' ? d.badRemMax : d.remMax) || 10)]; }
function mscRemArm(w) { const key = w === 'b' ? 'remB' : 'remQ'; clearTimeout(M_.tm[key]); delete M_.tm[key]; if (!M_.shown) return; const [a, b] = mscRemRange(w); const ms = (a + Math.random() * (b - a)) * 60000; M_.remAt[w] = Date.now() + ms; M_.tm[key] = setTimeout(() => mscRemFire(w), ms); }
/* 다시 알림 한 번: 여러 건이면 묶어서 한 말풍선 · 방금(최소 간격 안에) 말한 건은 뺌 · 숨은 탭이면 돌아올 때 */
