const mscAlDrop = (ack) => { Object.keys(M_.alRem || {}).forEach((x) => { if (x === ack || x.startsWith(ack + ':')) delete M_.alRem[x]; }); }; /* 'al:late'이면 그 종류의 건 모두 */
function mscAlArm() { if (M_.tm.al) return; M_.tm.al = setInterval(mscAlTick, 30000); }
const mscKst = () => new Date(mscNow() + 9 * 3600e3); /* 한국 시각(getUTC…로 읽음) */
