/* 지금 캐릭터를 쓰는 관리자(이 기기 빼고) */
function mscMsgTargets() { /* (정범님 10/28 12:14) 대상 = 책방 친구를 고른 다른 메시지 기기(관리자 기기 + MJ-MAIN·MJ-PHONE) · 예전 me.<기기> 칸에만 캐릭터가 있는 기기도 넣음(MJ-MAIN이 빠지던 까닭 중 하나) */ const D = (M_.doc && M_.doc.dev) || {}, L = (M_.doc && M_.doc.me) || {}, me = mscDev().toUpperCase(); const seen = new Set(), out = []; [...new Set([...Object.keys(D), ...Object.keys(L)])].forEach((dv) => { const K = String(dv || '').trim(); if (!K || K.toUpperCase() === me || seen.has(K.toUpperCase())) return; const m = { ...(L[dv] || {}), ...(((D[dv] || {}).me) || {}) }; if (!m.charId || !mscMsgAdm(K)) return; const ch = mscChar(m.charId); if (!ch) return; seen.add(K.toUpperCase()); out.push({ dev: K, name: m.name || K, char: m.charId, chName: ch.name || (MSC_DES[mscBaseOf(ch)] || {}).name || m.charId }); }); return out.sort((a, b) => a.name.localeCompare(b.name)); }
const MSC_GEST_ALL = () => [...new Set([...Object.keys(MSC_IDA), ...Object.keys(MSC_HAB), ...Object.keys(MSC_ACTS)])];
const mscGestName = (k) => MSC_IDLE_N[k] || ({ guard: '무술 준비 자세', shy: '부끄러워 볼 가리기', tickle: '간지럼 웃음', tuck: '머리 넘기기', push: '안경 올리기', head: '머리 긁적', chin: '턱 괴기', sip: '한 모금', shrug: '어깨 으쓱', bounce: '통통', stretch: '좌우 스트레칭', nod: '끄덕끄덕', headshake: '도리도리(아니)', lookup: '하늘 올려다보기', proud: '가슴 펴고 뿌듯' })[k] || k;
