const mscMsgLife = (d) => Math.min(MSC_MSG.maxLife, Math.max(MSC_MSG.life, ((d && d.text) || '').length * MSC_MSG.perChar + 2200, d && d.gesture ? ((mscActOf(d.gesture) || {}).ms || 0) + 2400 : 0));
