    if (d.mview) { const v = d.mview; if (mscViewOf(mscMine()) === v) return; M_.doc = { ...(M_.doc || {}), me: { ...((M_.doc || {}).me || {}), [mscDev()]: { ...mscMine(), view: v } } }; mscApply(); return mscSaveMe({ view: v }, v === 'bust' ? '🐾 반신 보기(허리 위) — 이 기기에 저장' : '🐾 전신 보기 — 이 기기에 저장'); }
    if (d.mpick) { if (mscMine().charId === d.mpick && mscChar(d.mpick)) { M_.pickCloseN = (M_.pickCloseN || 0) + 1; return mscPanel(false); } /* (r16 · 정범님 10/30) 이미 고른 캐릭터(✓ 내 캐릭터)를 한 번 더 누르면 창 닫힘 */ if (!mscMine().name && !(document.getElementById('msc_name') || {}).value) { toast('먼저 내 이름을 넣어 주세요', 1); const n = document.getElementById('msc_name'); if (n) n.focus(); return; } const ok = await mscClaim(d.mpick); if (ok && mscInScope() && !mscOpen()) { try { localStorage.setItem('rn-msc-open', '1'); } catch (x) {} mscSaveMe({ open: true }); } return; }
    if (d.mpha) { const i = document.getElementById('msc_phn'); const t = (i && i.value.trim()) || ''; if (!t) return toast('추가할 문구를 넣으세요', 1); return mscSaveCfg({ phrases: [...C().phrases, t] }, '✓ 응원 문구를 더했어요 — 모든 기기에 바로'); }
    if (d.mphd != null) { if (!mscArm(b, '이 문구 지움')) return; const L = [...C().phrases]; const [gone] = L.splice(+d.mphd, 1); return mscSaveCfg({ phrases: L }, '✓ 응원 문구를 지웠어요', { removed: [gone] }); }
    if (d.mphdef) { const L = C().phrases; const add = MSC_PHRASES.filter((x) => !L.includes(x)); if (!add.length) return toast('기본 문구가 이미 모두 있어요'); return mscSaveCfg({ phrases: [...L, ...add] }, `✓ 기본 문구 ${add.length}개를 더했어요`); }
    if (d.maldef) { if (!mscArm(b, '캐릭터 알림을 기본으로')) return; const z = {}; MSC_AL.forEach((a) => (z[a[0]] = { on: !!a[4], rep: 0 })); return mscSaveMe({ alerts: z }, '🔔 캐릭터 알림을 기본(넷만 켜짐)으로 — 이 기기만'); }
