    if (d.mcadd) { const L = chars(); const nc = { id: 'c' + Date.now().toString(36), name: '새 친구', base: 'n_bogi', c1: '#7A5C4A', c2: '#5E6E8A', c3: '#C0703F', desc: '' }; const j = L.findIndex((c) => mscSig(c) === mscSig(nc)); if (j >= 0) return toast(`'${L[j].name}'와(과) 모양·색이 똑같은 캐릭터가 이미 있어요 — 그 캐릭터의 모양이나 색을 먼저 바꾼 뒤 더해 주세요`, 1); L.push(nc); return mscSaveCfg({ chars: L }, '✓ 캐릭터를 더했어요 — 이름·모양·색을 바꿔 주세요'); }
