function mscCuDlp() { const ov = document.getElementById('msc_cu'), d = document.getElementById('dlp'); const box = ov && ov.querySelector('.box'), bar = ov && ov.querySelector('.hd .acts'); const fx = !!bar && getComputedStyle(bar).position === 'fixed'; if (!box || !fx) { if (box) box.style.removeProperty('--dlph'); if (d) { d.style.bottom = ''; d.style.maxHeight = ''; d.style.overflow = ''; } return; } const bh = Math.ceil(bar.getBoundingClientRect().height); if (d) { d.style.bottom = bh + 6 + 'px'; d.style.maxHeight = '30vh'; d.style.overflow = 'auto'; } const dh = d ? Math.ceil(d.getBoundingClientRect().height) : 0; box.style.setProperty('--dlph', dh ? dh + 10 + 'px' : '0px'); }
