  if (tab === 'face') return MSC_FACES.filter((k) => sxOk(MSC_FACE[k].sx)).map((k) => [k, MSC_FACE[k].n]); if (tab === 'eye') return MSC_EYES.filter((k) => sxOk(MSC_EYE[k].sx)).map((k) => [k, MSC_EYE[k].n]); if (tab === 'brow') return Object.entries(MSC_BROW).map(([k, v]) => [k, v[0]]);
