  for (let i = 0; i <= N; i++) { const u = i / N; const a = bz(Math.max(0, u - 0.02)), b = bz(Math.min(1, u + 0.02)); let dx = b[0] - a[0], dy = b[1] - a[1]; const l = Math.hypot(dx, dy) || 1; dx /= l; dy /= l; const c = bz(u); const s = (bend || 0) * Math.sin(Math.PI * 2 * u) * w0 * 0.35; const cc = [c[0] - dy * s, c[1] + dx * s]; const ts = tipK || 0.5; const w = (w0 * (u < ts ? 0.88 + 0.12 * Math.sin((Math.PI * u) / ts / 2) : Math.pow(Math.max(0, 1 - (u - ts) / (1 - ts)), 1.25))) / 2; /* (fix_face 2묶음 · 코디네이터 '앞머리 다발 끝 뾰족') 끝 가늘어짐 지수 0.85 → 1.25(오목 = 붓끝) */ /* 다발은 대부분 제 폭 · 끝쪽에서만 뾰족(89b08ee2) — 뿌리부터 가늘면 '물줄기'처럼 보임 */ P.push([hx(cc[0] - dy * w), hy(cc[1] + dx * w)]); Q.push([hx(cc[0] + dy * w), hy(cc[1] - dx * w)]); mid.push([hx(cc[0]), hy(cc[1])]); }
