        const side = (sg) => { const X = (x) => sg * x; const P = [[X(at(o.eyY) - 0.035), o.eyY - 0.01], [X(at(o.eyY + 0.04) + 0.012), o.eyY + 0.04], [X(at(0.7) + 0.03), 0.7], [X(at(0.86) + 0.045), 0.88], [X(hw * 0.5), 1.0], [X(hw * 0.4), 1.06, 1], [X(hw * 0.3), 0.98], [X(hw * 0.38), 0.86, 1], [X(hw * 0.5), mY - 0.01], [X(at(0.66) - 0.07), 0.68, 1], [X(at(o.eyY + 0.08) - 0.05), o.eyY + 0.1]]; return clump(P); };
